T["Dungeon maps have no coordinates. Click here, then on the spot where you stand. Done at two distant spots, Oasis shows you and your group on the map - for the whole guild."] = "地下城地图没有坐标。点击这里，然后点击地图上你当前所在的位置。在两个相距较远的位置完成后，Oasis会在地图上显示你和你的队伍 - 对整个公会可见。"
T["The guild will be notified"] = "公会会收到通知"
T["The guild can see whom you react to. Default: off"] = "公会会看到你在回复谁。默认：关"
