T["The guild isn't looking for anything from this dungeon."] = "公会目前没有在找此地下城的东西。"
T["Your guild doesn't award loot points yet - your values appear once the raid leaders start a raid."] = "公会尚未分配战利品点数 - 团队领导开始团队副本后会显示你的数值。"
T["The guild bank hasn't been read yet"] = "尚未读取公会银行"
T["The guild leadership names raid leaders and assistants under Crown > Modules > Raids & Loot (by name or from a guild rank). In a running raid, the raid leader and assistants count too."] = "公会管理在王冠 > 模块 > 团队与战利品中指定团队领袖和助理（名字或按公会会阶）。进行中的团队副本中，团队领袖和助理也算。"
T["The guild leadership names raid leaders under Crown > Modules > Raids & Loot. In a running raid, the raid leader and assistants count too."] = "公会管理在王冠 > 模块 > 团队与战利品中指定团队领袖。进行中的团队副本中，团队领袖和助理也算。"
T["The guild leadership names raid leaders under Crown > Modules > Raids & Loot. In a running raid, the raid leader counts too."] = "公会管理在王冠 > 模块 > 团队与战利品中指定团队领袖。进行中的团队副本中，团队领袖也算。"
T["The guild leadership only allows group searches from a higher rank."] = "公会管理只允许更高会阶创建组队招募。"
