T["The shortcuts are also in WoW's key bindings under AddOns > Oasis. Esc closes the Oasis window (not in combat - there Esc belongs to the game)."] = "这些快捷键也在魔兽按键设置的插件 > Oasis中。Esc关闭Oasis窗口（战斗中不行 - 那时Esc归游戏使用）。"
T["The shortcuts are also in WoW's key bindings under AddOns > Oasis. Esc closes the Oasis window as long as you last clicked into it."] = "这些快捷键也在魔兽按键设置的插件 > Oasis中。只要你最后点击过Oasis窗口，Esc就会关闭它。"
T["The bar rolls up out of view; move the mouse to the top edge and it comes down (only when docked at the top)"] = "工具栏会向上收起；将鼠标移到屏幕顶部边缘它会下来（仅在顶部停靠时）"
