T["When someone orders something from you or your profession (and when your order is done)"] = "有人向你或你的专业下订单时（以及你的订单完成时）"
T["When someone comes online"] = "有人上线时"
T["Who"] = "谁"
T["Who sends data that others reject (no permission, forged author, made-up entries). An unmodified Oasis practically never does this - a hint, not proof."] = "发送了被其他人拒绝的数据的人（无权限、伪造来源、虚构条目）。未修改的Oasis几乎不会这样 - 这只是提示，不是证据。"
T["Anyone who registers interest appears in a matching slot. Once there is an event, sign up directly on its card."] = "表示兴趣的人会出现在这里合适的位置。活动确定后，直接在卡片上报名。"
T["Who in the guild has the item on their wishlist"] = "公会中谁的愿望单上有此物品"
T["Who sees this section in the navigation (leadership always sees everything)"] = "谁能在导航中看到此模块（公会管理始终能看到全部）"
T["Who left the guild or was removed. If someone returns, Oasis notifies guild management."] = "离开公会或被移除的人。如有人回来，Oasis会通知公会管理。"
T["Who sees the crown at the top. Without rights it is grey and only opens a preview."] = "谁能看到顶部的王冠。无权限时王冠为灰色，只打开预览。"
T["Who may pin a message at the top of guild chat"] = "谁可以在公会聊天顶部置顶消息"
T["Who can invite is not known yet - log in once with your main and Oasis will remember the guild leadership."] = "尚不知道谁有邀请权限 - 用你的大号登录一次，Oasis会记住公会管理。"
T["Anyone up for %s? I'm looking for %s"] = "谁一起去%s？我在找%s"
T["Who has ...?"] = "谁有……？"
T["Who has the quest item you need? And whom can you help?"] = "谁有你需要的任务物品？你又能帮谁？"
T["Who got what"] = "谁得到了什么"
T["Who may book points (effort/loot) in raid."] = "谁可以在团队中记录点数（出勤/战利品）。"
T["Who in your group or raid has which buffs - and what's missing"] = "队伍或团队中谁有哪些增益 - 还缺什么"
T["Who is ready? Status lights per player"] = "谁已就绪？每位玩家的状态灯"
T["Who is already saved this week, who is free and attuned – mains and alts"] = "本周谁已锁定，谁空闲且已解锁 - 大号和小号"
T["Who's online"] = "谁在线"
T["Who is online?"] = "谁在线？"
T["Who is online when"] = "谁在什么时间在线"
T["Who is how far"] = "谁进度如何"
T["Who crafts what, market, guild bank"] = "谁能制作什么、市场、公会银行"
T["Who could join: %s"] = "可能同去的：%s"
T["Who could join?"] = "谁可能同去？"
T["Whoever shows up often and has received little gets first pick on 'Need'. Part of the points decays every week."] = "经常参加且获得较少的人在“需求”时优先。每周会衰减一部分点数。"
T["Anyone who signs up with a fitting role is invited to your group right away."] = "以合适职责报名的人会立即被邀请到你的队伍。"
T["Who stands where with which faction? Close to the goal, farm together, progress this week"] = "谁在哪个阵营的什么声望？即将达成、一起刷、本周进度"
T["Who deals, heals and takes the most?"] = "谁输出最多、治疗最多、承受最多？"
T["The guild master decides who belongs to the leadership under Crown > Guild."] = "公会管理成员由会长在王冠 > 公会中设定。"
T["Stats"] = "属性"
T["stats do nothing for your role"] = "这些属性对你的职责无用"
T["stats for info only"] = "属性仅供参考"
T["Stats, yearbook, daily goal, records and adventures of your character."] = "你角色的属性、年鉴、每日目标、纪录和冒险。"
T["Stats: +healing, intellect, spirit, mp5;Weapon: staff or one-hander + off-hand with healing;Healing: Rejuvenation and Regrowth ahead, Healing Touch for big hits;Tip: Innervate for mana, Rebirth for fallen healers"] = "属性：+治疗、智力、精神、法力回复;武器：法杖或单手武器 + 带治疗的副手;治疗：预先回春术和愈合，大伤害用治疗之触;提示：用激活回蓝，用复生救倒下的治疗"
T["Stats: +healing, intellect, spell crit (Illumination refunds mana), mp5;Weapon: one-hander + off-hand/shield with healing;Healing: Flash of Light for small damage, Holy Light (low rank) for big hits;Tip: hand out blessings, Divine Protection when you pull aggro"] = "属性：+治疗、智力、法术暴击（启迪返还法力）、法力回复;武器：单手武器 + 带治疗的副手/盾牌;治疗：小伤害用圣光闪现，大伤害用圣光术（低级）;提示：分发祝福，被攻击时用圣佑术"
T["Stats: +healing, mp5, intellect - spirit does little;Weapon: one-hander + shield with healing;Healing: Chain Heal for groups, Healing Wave (low rank) for the tank;Tip: drop Mana Spring Totem, Earth Shield on the tank"] = "属性：+治疗、法力回复（MP5）、智力 - 精神作用不大;武器：单手武器 + 带治疗的盾牌;治疗：团队用治疗链，坦克用治疗波（低级）;提示：放置法力之泉图腾，给坦克上大地之盾"
T["Stats: +healing, spirit (Meditation: regen while casting), intellect, mp5;Weapon: staff or one-hander + off-hand with healing, wand;Healing: Renew and Power Word: Shield ahead, Greater Heal (low rank) for the tank;Tip: Prayer of Healing for the group, Fade on aggro"] = "属性：+治疗、精神（冥想：施法时也回复）、智力、法力回复;武器：法杖或单手武器 + 带治疗的副手、魔杖;治疗：预先恢复和真言术：盾，坦克用强效治疗术（低级）;提示：队伍用治疗祷言，仇恨过高时用渐隐术"
T["Stats: armor (bear form multiplies it), stamina, agility (dodge + armor);Weapon: damage doesn't matter - only the stats (staff/polearm with stamina);Rotation: Maul, Swipe for packs, Demoralizing Roar;Tip: strength for more threat, Enrage to start"] = "属性：护甲（熊形态大幅提升）、耐力、敏捷（躲闪 + 护甲）;武器：对伤害无影响 - 只看属性（带耐力的法杖/长柄武器）;循环：槌击、挥击打群体、挫志咆哮;提示：力量增加威胁，开场用激怒"
T["Stats: strength (1 point = 2 AP), agility (AP + crit), crit, hit up to +9 %;Weapon: damage doesn't matter - only the stats;Rotation: Claw/Shred for combo points, then Ferocious Bite;Tip: powershift (recast form) for energy, open from stealth"] = "属性：力量（1点 = 2攻击强度）、敏捷（攻击强度 + 暴击）、暴击、命中至+9 %;武器：对伤害无影响 - 只看属性;循环：爪击/撕碎攒连击点，然后凶猛撕咬;提示：用变形重置（重新变形）回能量，从潜行中突袭"
T["Stats: strength (1 point = 2 AP), crit (procs Flurry = faster swings), hit up to +9 %;Weapon: slow two-hander - Windfury procs per swing, so slower = more damage;Rotation: Windfury Weapon, Stormstrike, Earth Shock;Tip: Strength of Earth and Windfury Totem for the group"] = "属性：力量（1点 = 2攻击强度）、暴击（触发乱舞 = 攻速更快）、命中至+9 %;武器：慢速双手武器 - 风怒按每次攻击触发，越慢伤害越高;循环：风怒武器、风暴打击、地震术;提示：为队伍放置大地之力图腾和风怒图腾"
T["Stats: strength (1 point = 2 AP), crit, hit up to +9 %;Weapon: slow two-hander - seals and Judgement scale per swing;Rotation: Seal of Righteousness/Command, Judgement, reapply seal;Tip: Consecration only with enough mana, Blessing of Might on yourself"] = "属性：力量（1点 = 2攻击强度）、暴击、命中至+9 %;武器：慢速双手武器 - 圣印和审判按每次攻击生效;循环：正义圣印/命令圣印、审判、重新施放圣印;提示：法力充足时才用奉献，给自己上力量祝福"
T["Stats: hit up to +9 %, agility (1 AP, ~29 = 1 % crit), AP, crit;Weapon: Combat = fast off-hand, slow main hand (Sinister Strike); daggers for Backstab;Rotation: build combo points, keep Slice and Dice up, then Eviscerate;Tip: dual wielding misses white hits more often - hit matters most"] = "属性：命中至+9 %、敏捷（1攻击强度，约29 = 1 %暴击）、攻击强度、暴击;武器：战斗 = 快速副手、慢速主手（邪恶攻击）; 刺杀用匕首;循环：攒连击点、保持切割、然后剔骨;提示：双持时普通攻击更容易未命中 - 命中最重要"
T["Stats: hit up to +9 %, agility (2 ranged AP, ~53 = 1 % crit), AP, intellect;Weapon: slow ranged weapon (big damage per shot), melee weapon for stats;Rotation: Hunter's Mark, Auto Shot, Aimed Shot/Multi-Shot in between;Tip: feed your pet and keep it happy, Freezing Trap (square) for control"] = "属性：命中至+9 %、敏捷（2远程攻击强度，约53 = 1 %暴击）、攻击强度、智力;武器：慢速远程武器（每发伤害高）、带属性的近战武器;循环：猎人印记、自动射击、穿插瞄准射击/多重射击;提示：喂养宠物并保持快乐，冰冻陷阱（方块）用于控制"
T["Stats: hit up to +9 %, strength (1 point = 2 AP), crit (~20 agility = 1 %);Weapon: slow two-hander (Mortal Strike, Heroic Strike scale per swing);Rotation: build rage, Mortal Strike / Bloodthirst, Whirlwind, spare rage into Heroic Strike;Tip: Battle Shout before the pull, Execute below 20 % health"] = "属性：命中至+9 %、力量（1点 = 2攻击强度）、暴击（约20敏捷 = 1 %）;武器：慢速双手武器（致死打击、英勇打击按每次攻击生效）;循环：积攒怒气、致死打击/嗜血、旋风斩、多余怒气用英勇打击;提示：战前用战斗怒吼，20 %血量以下用斩杀"
T["Stats: defense (440 = crit immune vs bosses at 60), stamina, armor, block;Weapon: one-hander + shield, fast weapon = more rage;Rotation: Shield Slam/Revenge, Sunder Armor on the target, Heroic Strike with high rage;Tip: hit helps so Taunt and abilities don't miss"] = "属性：防御（60级440防御免疫首领暴击）、耐力、护甲、盾牌格挡;武器：单手武器 + 盾牌，快速武器 = 更多怒气;循环：盾牌猛击/复仇、对目标破甲、怒气多时用英勇打击;提示：命中有助于嘲讽和技能不被未命中"
T["Stats: defense, stamina, armor, then spell damage for more threat;Weapon: one-hander (ideally spell damage) + shield;Rotation: Righteous Fury on, Consecration for packs, keep Holy Shield up;Tip: mana is tight - use Seal of Wisdom or some intellect"] = "属性：防御、耐力、护甲，然后法术伤害以提高威胁;武器：单手武器（最好带法术伤害）+ 盾牌;循环：开启正义之怒、群体用奉献、保持神圣之盾;提示：法力紧张 - 带上智慧圣印或智力"
T["Stats: spell damage, spell crit (Elemental Focus saves mana), intellect, mp5;Weapon: one-hander + shield/off-hand with spell damage;Rotation: spam Lightning Bolt, Chain Lightning on packs, Flame Shock;Tip: spell hit up to +16 % in raids, Mana Spring Totem against oom"] = "属性：法术伤害、法术暴击（元素集中节省法力）、智力、法力回复;武器：单手武器 + 带法术伤害的盾牌/副手;循环：狂按闪电箭、群体用闪电链、烈焰震击;提示：团队中法术命中至+16 %，用法力之泉图腾防止空蓝"
T["Stats: spell damage, spell crit, intellect, spell hit up to +16 % in raids;Weapon: staff or one-hander + off-hand with spell damage;Rotation: Moonfire + Insect Swarm, then Wrath or Starfire;Tip: Innervate yourself when mana runs low"] = "属性：法术伤害、法术暴击、智力、团队中法术命中至+16 %;武器：法杖或单手武器 + 带法术伤害的副手;循环：月火术 + 虫群，然后愤怒或星火术;提示：法力紧张时给自己用激活"
T["Stats: spell damage, spell hit up to +16 % (raid), stamina, intellect;Weapon: staff or dagger + off-hand with spell damage, wand for leftover mana;Rotation: Corruption + curse, then Shadow Bolt; Life Tap instead of drinking;Tip: stamina pays off twice (Life Tap, Voidwalker/Soul Link)"] = "属性：法术伤害、法术命中至+16 %（团队）、耐力、智力;武器：法杖或匕首 + 带法术伤害的副手，魔杖用于剩余法力;循环：腐蚀术 + 诅咒，然后暗影箭; 用生命分流代替喝水;提示：耐力有双重收益（生命分流、虚空行者/灵魂链接）"
T["Stats: spell damage, spell hit up to +16 % (raid), spirit for mana;Weapon: staff or one-hander + off-hand with spell damage;Rotation: Shadow Word: Pain, Mind Blast, Mind Flay;Tip: stay in Shadowform, Vampiric Embrace heals the group"] = "属性：法术伤害、法术命中至+16 %（团队）、精神回法力;武器：法杖或单手武器 + 带法术伤害的副手;循环：暗言术：痛、心灵震爆、精神鞭笞;提示：保持暗影形态，吸血鬼的拥抱治疗队伍"
T["Stats: spell damage, then spell hit up to +16 % (raid bosses), intellect, spell crit;Weapon: staff with spell damage, plus a wand for leftover mana;Rotation: spam Frostbolt or Fireball, Evocation when out of mana;Leveling: intellect and spirit = less downtime, sheep (moon) in groups"] = "属性：法术伤害，然后法术命中至+16 %（团队首领）、智力、法术暴击;武器：带法术伤害的法杖，加一根魔杖用于剩余法力;循环：狂按寒冰箭或火球术，空蓝时用唤醒;升级：智力和精神 = 更少休息，组队时用变羊（月亮）"
