T["Shows BETTER / WORSE / CAN'T EQUIP with effect (DPS, health, armor) and a stats table. Blizzard's comparison then only appears with Shift. If nesUI is loaded with its own comparison, Oasis shows nothing (avoids doubles) - turn it off there with /nes vergleich."] = "显示更好/更差/无法穿戴及影响（DPS、生命值、护甲）和属性表。暴雪的比较需按Shift才显示。如已加载自带比较的nesUI，Oasis不显示（否则重复）- 可在那里用/nes vergleich关闭。"
T["Shows better / worse / can't equip with effect (DPS, health, armor) and a stats table. Blizzard's comparison then only appears with Shift. If nesUI with its own comparison is loaded, Oasis shows nothing (otherwise doubled) - turn it off there with /nes vergleich."] = "显示更好/更差/无法穿戴及影响（DPS、生命值、护甲）和属性表。暴雪的比较需按Shift才显示。如已加载自带比较的nesUI，Oasis不显示（否则重复）- 可在那里用/nes vergleich关闭。"
