T["1.  Keep the combat log on (Settings > Areas > Combat board, on by default).\n2.  After playing, double-click ImportCrits.bat in the Oasis folder.\n3.  /reload in game - your highest crit shows here and is shared with the guild."] = "1.  保持战斗日志开启（设置 > 模块 > 战斗排行榜，默认开启）。\n2.  游戏结束后，双击 Oasis 文件夹中的 ImportCrits.bat。\n3.  在游戏中 /reload - 你的最高暴击会显示在这里并与公会共享。"
