T["Active members below the officer ranks appear in the 'Promotion' list after this many days in the same rank. 0 = off."] = "官员会阶以下的活跃成员在同一会阶停留这么多天后，会出现在“晋升”列表中。0 = 关闭。"
T["Current zone first"] = "当前区域优先"
T["All areas, grouped by topic: guild, playing together, raid, trade, fun. Click a heading to collapse its group."] = "所有模块按主题分组：公会、一起玩、团队、交易、娱乐。点击标题可折叠该组。"
